/// Field-split the `Td` for the WebPagesManager calls.
pub(crate) fn web_pages_env_split(
    td: &mut Td,
) -> (
    TdWebPagesEnv<'_>,
    &mut crate::web_pages_manager::WebPagesManager,
) {
    let crate::td::Td {
        global,
        option_manager,
        auth_manager,
        user_manager,
        file_manager,
        file_load_manager,
        file_reference_manager,
        documents_manager,
        audios_manager,
        videos_manager,
        voice_notes_manager,
        video_notes_manager,
        web_pages_manager,
        web_pages_timeouts,
        ..
    } = td;
    (
        TdWebPagesEnv {
            global,
            options: option_manager.as_mut(),
            auth_is_bot: auth_manager.is_bot(),
            user_manager,
            file_manager: std::sync::Arc::clone(file_manager),
            file_load_manager: std::sync::Arc::clone(file_load_manager),
            file_reference_manager,
            documents: documents_manager,
            audios: audios_manager,
            videos: videos_manager,
            voice_notes: voice_notes_manager,
            video_notes: video_notes_manager,
            web_pages_timeouts,
        },
        web_pages_manager,
    )
}

/// The `G()`/manager slice of the collapsed WebPagesManager (M.17).
